begin;
create extension if not exists pgcrypto;
create table if not exists public.angelcare_marketplace_hospitality_properties(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.angelcare_marketplace_b2b_organizations(id) on delete cascade,property_code text not null,name text not null,property_type text not null,category_label text,room_count int,family_guest_volume int,seasonality_profile text,kids_facilities jsonb not null default '{}',security_contact_id uuid references public.angelcare_marketplace_b2b_contacts(id),guest_languages text[] not null default '{}',status text not null default 'configuration' check(status in('configuration','readiness_review','approved','active','paused','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,property_code));
create table if not exists public.angelcare_marketplace_hospitality_seasons(id uuid primary key default gen_random_uuid(),property_id uuid not null references public.angelcare_marketplace_hospitality_properties(id) on delete cascade,season_key text not null,name_fr text not null,starts_on date not null,ends_on date not null,expected_family_volume int,peak_days text[] not null default '{}',status text not null default 'planned' check(status in('planned','confirmed','active','completed','cancelled')),unique(property_id,season_key),check(ends_on>=starts_on));
create table if not exists public.angelcare_marketplace_hospitality_programs(program_id uuid primary key references public.angelcare_marketplace_b2b_programs(id) on delete cascade,property_id uuid not null references public.angelcare_marketplace_hospitality_properties(id),season_key text,guest_booking_mode text check(guest_booking_mode in('hotel_desk','concierge','guest_app','room_qr','manual','mixed')),age_min int,age_max int,operating_hours jsonb not null default '{}',guest_languages text[] not null default '{}',activity_catalog jsonb not null default '[]',staffing_requirements jsonb not null default '{}',safety_checklist jsonb not null default '[]',equipment_requirements jsonb not null default '[]',hotel_approved boolean not null default false,hotel_approved_by uuid,hotel_approved_at timestamptz,check(age_min is null or age_min>=0),check(age_max is null or age_max>=coalesce(age_min,0)));
create table if not exists public.angelcare_marketplace_hospitality_guest_service_rules(id uuid primary key default gen_random_uuid(),property_id uuid not null references public.angelcare_marketplace_hospitality_properties(id) on delete cascade,rule_key text not null,title_fr text not null,service_type text not null,consent_required boolean not null default true,minimum_notice_minutes int,maximum_duration_minutes int,room_service_allowed boolean not null default false,security_handover_required boolean not null default true,configuration jsonb not null default '{}',status text not null default 'draft' check(status in('draft','review','approved','active','paused','archived')),unique(property_id,rule_key));
create table if not exists public.angelcare_marketplace_hospitality_feedback(id uuid primary key default gen_random_uuid(),program_id uuid not null references public.angelcare_marketplace_b2b_programs(id),property_id uuid not null references public.angelcare_marketplace_hospitality_properties(id),guest_reference text,booking_reference text,rating int check(rating between 1 and 5),feedback_text text,language text,incident_flag boolean not null default false,follow_up_status text not null default 'not_required',created_at timestamptz not null default now());
insert into public.angelcare_marketplace_permissions(permission_key,name,category,sensitive) values('marketplace.b2b.hospitality.view','Voir Hospitality Command','B2B Hospitality',false),('marketplace.b2b.hospitality.manage','Gérer propriétés et programmes','B2B Hospitality',true),('marketplace.b2b.hospitality.approve','Approuver les programmes Hospitality','B2B Hospitality',true) on conflict(permission_key) do update set name=excluded.name,category=excluded.category,sensitive=excluded.sensitive;
insert into public.angelcare_marketplace_role_permissions(role_key,permission_key) select r.role_key,p.permission_key from public.angelcare_marketplace_roles r cross join public.angelcare_marketplace_permissions p where r.role_key in('marketplace_super_admin','marketplace_executive') and p.permission_key like 'marketplace.b2b.hospitality.%' on conflict do nothing;
update public.angelcare_marketplace_modules set status='enabled',enabled=true,health_status='healthy',route_prefix='/angelcare-marketplace/admin/verticals/hospitality',required_permissions=array['marketplace.b2b.hospitality.view']::text[],version=version+1,updated_at=now() where introduced_by_mega_zip=13;
insert into public.angelcare_marketplace_feature_flags(flag_key,name,description,enabled,status,reason) values('marketplace.b2b.hospitality.enabled','Hotels & Hospitality','Kids clubs, guest childcare, concierge et saisonnalité.',true,'active','Ultra Delivery 3/5 · Original MZ13') on conflict(flag_key) do update set enabled=true,status='active',reason=excluded.reason,updated_at=now();
alter table public.angelcare_marketplace_hospitality_properties enable row level security;alter table public.angelcare_marketplace_hospitality_seasons enable row level security;alter table public.angelcare_marketplace_hospitality_programs enable row level security;alter table public.angelcare_marketplace_hospitality_guest_service_rules enable row level security;alter table public.angelcare_marketplace_hospitality_feedback enable row level security;
revoke all on table public.angelcare_marketplace_hospitality_properties,public.angelcare_marketplace_hospitality_seasons,public.angelcare_marketplace_hospitality_programs,public.angelcare_marketplace_hospitality_guest_service_rules,public.angelcare_marketplace_hospitality_feedback from anon,authenticated;grant all on table public.angelcare_marketplace_hospitality_properties,public.angelcare_marketplace_hospitality_seasons,public.angelcare_marketplace_hospitality_programs,public.angelcare_marketplace_hospitality_guest_service_rules,public.angelcare_marketplace_hospitality_feedback to service_role;
commit;
